<?php /* Approve day / Reject day for a reviewer: $uid, $date, $name (person), $list (the day's entries), optional $sm (small buttons). Needs partials/reject_dialog on the page. */
$stopped = array_filter($list, static fn ($x) => !$x['is_running']);
$rej = count(array_filter($stopped, static fn ($x) => $x['status'] === 'rejected'));
$sm = !empty($sm) ? ' sm' : '';
if ($stopped): ?><span class="dr-acts"><?php if ($rej): ?><form method="post" action="<?= e(url('/time/review/day')) ?>" data-confirm="Approve every entry of <?= e(fdate($date, 'l, d M')) ?>?"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) $uid ?>"><input type="hidden" name="date" value="<?= e($date) ?>"><input type="hidden" name="decision" value="approved"><button class="btn mint<?= $sm ?>" title="Approve the <?= $rej ?> rejected entr<?= $rej === 1 ? 'y' : 'ies' ?> of this day"><?= icon('check', 'sm') ?> Approve day</button></form><?php else: ?><button type="button" class="btn ghost<?= $sm ?>" disabled title="Every entry of this day is approved"><?= icon('check', 'sm') ?> Approve day</button><?php endif ?><button type="button" class="btn danger<?= $sm ?>" data-modal="day-reject" data-reject-user="<?= (int) $uid ?>" data-reject-date="<?= e($date) ?>" data-reject-name="<?= e($name.', '.fdate($date, 'l, d M Y')) ?>"><?= icon('x', 'sm') ?> Reject day</button></span><?php endif;
